 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The 2-colored edge is the boundary. A colored object moves toward it
    # until it is one cell from the boundary; mark its former edge with 8.
    if all(row[0] == 2 for row in g):
        bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
        pts = [(r, c) for r in range(h) for c in range(1, w) if g[r][c] != bg and g[r][c] != 2]
        if not pts:
            return g
        left, right = min(c for r,c in pts), max(c for r,c in pts)
        obj = [(r,c,g[r][c]) for r,c in pts]
        shift = 1-left
        # Clear the old object and place the same shape adjacent to boundary.
        for r,c,v in obj:
            g[r][c] = bg
        for r,c,v in obj:
            g[r][c+shift] = v
        mark = right + shift + 1
        if 0 <= mark < w:
            for r in range(h):
                g[r][mark] = 8
        return g
    # Horizontal boundary: preserve the object and mark the next row beyond it.
    if all(v == g[0][0] for v in g[0]) and g[0][0] == 2:
        bg = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
        pts = [(r,c) for r in range(h) for c in range(w) if g[r][c] not in (bg,2)]
        if pts:
            edge = max(r for r,c in pts)
            if edge+1 < h:
                g[edge+1] = [8]*w
        return g
    return g

